{"file_path":"tests/test_metrics.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_exactly_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 5) == 3
    assert flags_in_window([1, 2], 0) == 0


def test_parse_transcript_log_fields_and_skips():
    assert parse_transcript_log([
        "  # comment",
        "  ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


def test_parse_transcript_log_errors_include_input_line_number():
    with pytest.raises(ValueError, match="line 3"):
        parse_transcript_log(["# skipped", " ", "bad,fields"])
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["x,1,1", "x,nope,0"])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "b", "day": 2, "flagged": True},
        {"id": "a", "day": 3, "flagged": False},
        {"id": "b", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_and_clipped():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": None},
        {"day": 3, "flagged": True},
        {"day": 8, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 1, 0]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_spec_fields_and_rounding():
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [{"day": 1, "flagged": False}, {"day": 4, "flagged": True}],
        "empty": [],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
        "b": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["a", "z", "b"]


def test_flag_rate_by_group_sorted_and_empty_is_none():
    assert flag_rate_by_group({"z": [], "b": [{"flagged": True}], "a": [{"flagged": False}]}) == {
        "a": 0.0, "b": 1.0, "z": None
    }


def test_longest_flag_streak_counts_positive_entries():
    assert longest_flag_streak([1, 2, 0, -1, 3]) == 2
    assert longest_flag_streak([]) == 0
